  "Green Tea Shot": { label: "Shot", ingredients: ["0.5 oz Jameson Irish Whiskey", "0.5 oz peach schnapps", "0.5 oz sour mix", "Splash of Sprite"], instructions: "Combine Jameson, peach schnapps, and sour mix in a shaker with ice. Shake well and strain into a shot glass. Top with a splash of Sprite. Does not contain actual green tea." },
  "Black & Tan": { label: "Beer Cocktail", ingredients: ["Half pint pale ale or lager (e.g. Bass)", "Half pint Guinness stout"], instructions: "Pour the pale ale into a pint glass first. Then slowly pour the Guinness over the back of a spoon held just above the surface so it floats on top. Serve without stirring." },
